// ---------- Round 15: agent playground / team designer / cost estimator, automation hub tabs, Module 3 artifact & design studio, failure gallery, Module 6 build-alongs, Studio cleanup ----------
const UX21={play:T('Playground','الملعب'),team:T('Team designer','مصمم الفريق'),cost:T('Cost & time','التكلفة والوقت'),design:T('Designer','المصمم'),find:T('Automation finder','مكتشف الأتمتة'),recipes:T('Recipes','وصفات'),matrix:T('Approval matrix','مصفوفة الموافقات'),risk:T('Risk register','سجل المخاطر'),fix:T('Fix & re-enhance','صلّح وحسّن'),saved:T('My saved prompts','برومبتاتي المحفوظة'),fails:T('Failure gallery','معرض الأخطاء'),ba:T('Build-along projects','مشروعات ابني معانا'),m3:T('Artifact & design studio','استوديو الـ Artifacts والتصميم')};
const nowISO=()=>new Date().toISOString().slice(0,10);
const ntf=(id,t)=>{const e=document.getElementById(id);if(e)e.textContent=t};

// ===== Agent builder: more tabs =====
{const _ab=vAgentB;vAgentB=function(){const extra=[['play','🧪',UX21.play],['team','🕸',UX21.team],['cost','⏱',UX21.cost]];const btns=extra.map(t=>`<button class="tab ${AGTAB===t[0]?'on':''}" data-agtab="${t[0]}">${t[1]} ${L(t[2])}</button>`).join('');
if(!['play','team','cost'].includes(AGTAB))return _ab().replace(/(<div class="tabs big">[\s\S]*?)(<\/div>)/,'$1'+btns+'$2');
const keep=AGTAB;AGTAB='guide';let head;try{head=_ab()}finally{AGTAB=keep}const m=head.match(/^<h1>[\s\S]*?<\/h1><div class="tabs big">[\s\S]*?<\/div>/);const tabs=(m?m[0]:'').replace(/ on"/g,'"').replace(/(<div class="tabs big">[\s\S]*?)(<\/div>)$/,'$1'+btns+'$2');
crumb(L(UX4.agentb)+' › '+L(extra.find(x=>x[0]===AGTAB)[2]));return tabs+(AGTAB==='play'?vPlay():AGTAB==='team'?vTeam():vCost())}}

// --- 1. Agent playground: a real tool-using run with an approval gate (all sends are simulated)
let PG=Object.assign({goal:'',data:'ar_aging',appr:true,trace:[],out:'',busy:false},ST.pg||{});PG.busy=false;let PGCTL=null,PGWAIT=null;
function savePG(){const {busy,...r}=PG;r.trace=(r.trace||[]).slice(-40);ST.pg=r;saveST()}
function calcExpr(s){let i=0;s=String(s).replace(/\s+/g,'').replace(/,/g,'');const peek=()=>s[i];const num=()=>{let m=s.slice(i).match(/^\d+(\.\d+)?/);if(!m)throw new Error('number expected at '+i);i+=m[0].length;return parseFloat(m[0])};
const fac=()=>{if(peek()==='-'){i++;return -fac()}if(peek()==='('){i++;const v=add();if(s[i++]!==')')throw new Error(') expected');return v}const v=num();if(peek()==='%'){i++;return v/100}return v};
const mul=()=>{let v=fac();while(peek()==='*'||peek()==='/'){const o=s[i++];const r=fac();v=o==='*'?v*r:v/r}return v};const add=()=>{let v=mul();while(peek()==='+'||peek()==='-'){const o=s[i++];const r=mul();v=o==='+'?v+r:v-r}return v};
const v=add();if(i<s.length)throw new Error('unexpected '+s[i]);return Math.round(v*10000)/10000}
function pgTools(){const push=e=>{PG.trace.push(e);pgPaint()};return [
{name:'list_datasets',description:'Lists the sample datasets available to this agent with their columns. Returns name, title and columns.',execute(){const r=Object.keys(DATA).map(k=>({name:k,title:DATA[k].en,columns:DATA[k].csv.split('\n')[0]}));push({k:'tool',n:'list_datasets',i:'',o:r.length+' datasets'});return r}},
{name:'read_dataset',description:'Reads rows of one sample dataset as CSV text. Use the dataset name from list_datasets. Returns the header and up to max_rows rows.',inputSchema:{type:'object',properties:{name:{type:'string'},max_rows:{type:'number'}},required:['name']},execute(x){const k=String(x.name||'');if(!DATA[k])throw new Error('unknown dataset '+k);const n=Math.min(200,Math.max(1,Number(x.max_rows)||60));const rows=DATA[k].csv.split('\n');const out=rows.slice(0,n+1).join('\n');push({k:'tool',n:'read_dataset',i:k+' ('+Math.min(n,rows.length-1)+' rows)',o:(rows.length-1)+' rows in file'});return out}},
{name:'calculate',description:'Evaluates an arithmetic expression exactly (numbers, + - * / %, parentheses). Use it for every total, average, ratio or percentage. Returns the number.',inputSchema:{type:'object',properties:{expression:{type:'string'}},required:['expression']},execute(x){const r=calcExpr(x.expression);push({k:'tool',n:'calculate',i:String(x.expression).slice(0,120),o:String(r)});return r}},
{name:'save_draft',description:'Saves a draft document (memo, table, plan) for the human to review. Returns a confirmation.',inputSchema:{type:'object',properties:{title:{type:'string'},content:{type:'string'}},required:['title','content']},execute(x){push({k:'draft',n:'save_draft',i:String(x.title||'Draft'),o:String(x.content||'').slice(0,4000)});return 'Draft saved for review.'}},
{name:'send_message',description:'Sends an email or message to a person outside the team. A human must approve it first; returns approved or rejected. Only use for the final, reviewed message.',inputSchema:{type:'object',properties:{to:{type:'string'},subject:{type:'string'},body:{type:'string'}},required:['to','body']},async execute(x,ctx){const e={k:'send',n:'send_message',i:`${x.to||''} — ${x.subject||''}`,o:String(x.body||'').slice(0,2000),st:PG.appr?'wait':'auto'};push(e);
if(!PG.appr){e.st='sent';pgPaint();return 'Sent (simulated — nothing actually left the platform).'}
const ok=await new Promise(res=>{PGWAIT=res;ctx.signal.addEventListener('abort',()=>res(false))});PGWAIT=null;e.st=ok?'sent':'rejected';pgPaint();return ok?'Approved by the human and sent (simulated).':'Rejected by the human. Do not send. Revise or stop.'}}]}
function pgTrace(){const ar=LANG==='ar';return PG.trace.map((e,i)=>`<div class="pgev ${e.k}"><span class="pgn">${i+1}</span><div><b>${e.k==='plan'?'🧭':e.k==='draft'?'📝':e.k==='send'?'✉':'🔧'} ${esc(e.n)}</b>${e.i?` <span class="k">${esc(e.i)}</span>`:''}${e.o?`<div class="pgo" dir="auto">${esc(e.o).slice(0,1800)}</div>`:''}${e.k==='send'?`<div class="pgst">${e.st==='wait'?`⏸ ${ar?'مستني موافقتك':'Waiting for your approval'} <button class="btn-gold" data-pga="1">✓ ${ar?'وافق':'Approve'}</button><button class="tbtn" data-pga="0">✕ ${ar?'ارفض':'Reject'}</button>`:e.st==='sent'?'✓ '+(ar?'اتبعت (محاكاة)':'Sent (simulated)'):e.st==='rejected'?'✕ '+(ar?'اترفض':'Rejected'):''}</div>`:''}</div></div>`).join('')}
function pgPaint(){const b=document.getElementById('pgtrace');if(b){b.innerHTML=pgTrace()||`<p class="k">${LANG==='ar'?'لسه مفيش خطوات.':'No steps yet.'}</p>`;b.scrollTop=b.scrollHeight}}
function vPlay(){const ar=LANG==='ar';return `<p class="lede">${ar?'اديله هدف، وشوف الوكيل بيشتغل خطوة بخطوة: يخطط، يقرا البيانات، يحسب بأداة، يكتب مسودة — ويقف يستنى موافقتك قبل أي إرسال. كل الإرسال هنا محاكاة.':'Give the agent a goal and watch it work step by step: plan, read data, calculate with a tool, draft — and stop for your approval before anything is sent. All sending here is simulated.'}</p>
<div class="twocol"><div class="abpane"><label class="pbf"><b>${ar?'الهدف':'Goal'}</b><textarea class="search" id="pggoal" rows="4" dir="auto" placeholder="${ar?'مثلاً: رتّب العملاء المتأخرين في الدفع وجهّز رسالة متابعة لأكبر واحد':'e.g. Rank overdue customers and draft a follow-up email to the largest one'}">${esc(PG.goal)}</textarea></label>
<label class="pbf"><b>${ar?'البيانات اللي يبدأ بيها':'Starting dataset'}</b><select class="search" id="pgdata">${Object.keys(DATA).map(k=>`<option value="${k}" ${PG.data===k?'selected':''}>${esc(L(T(DATA[k].en,DATA[k].ar)))} (${k})</option>`).join('')}</select></label>
<label class="fdrun"><input type="checkbox" id="pgappr" ${PG.appr?'checked':''}> ${ar?'وقف لموافقتي قبل أي إرسال (موصى بيه)':'Pause for my approval before sending (recommended)'}</label>
<div class="row-btns"><button class="btn-gold" data-pg="run" ${PG.busy?'disabled':''}>${PG.busy?(ar?'الوكيل شغال…':'Agent running…'):'▶ '+(ar?'شغّل الوكيل':'Run the agent')}</button>${PG.busy?`<button class="tbtn" data-pg="stop">■ ${ar?'وقّف':'Stop'}</button>`:''}<button class="tbtn" data-pg="clear">${ar?'امسح':'Clear'}</button></div><p class="note" id="pgnote"></p>
<div class="chips">${(ar?['لخّص الموازنة قصاد الفعلي وطلّع أكبر 3 انحرافات','رتّب أولويات التحصيل وجهّز رسالة لأكبر عميل متأخر','قارن عروض الموردين واقترح الأفضل بمبررات']:['Summarise budget vs actual and find the 3 biggest variances','Prioritise collections and draft a message to the largest overdue customer','Compare supplier quotes and recommend one with reasons']).map((s,i)=>`<button class="chip" data-pgs="${i}" data-d="${['bva','ar_aging','suppliers'][i]}">${s}</button>`).join('')}</div></div>
<div class="abpane"><h3>🧭 ${ar?'خطوات الوكيل':'Agent steps'}</h3><div id="pgtrace" class="pgtrace">${pgTrace()||`<p class="k">${ar?'لسه مفيش خطوات.':'No steps yet.'}</p>`}</div>${PG.out?`<h3>✅ ${ar?'التسليم النهائي':'Final delivery'}</h3><div class="pgfinal">${fmtMD(PG.out)}</div>`:''}</div></div>`}
async function pgRun(){const ar=LANG==='ar';if(!PG.goal.trim()){ntf('pgnote',ar?'اكتب هدف الأول.':'Write a goal first.');return}const sample=await tutorSample();if(!sample){ntf('pgnote',ar?'الملعب بيشتغل لما المنصة تتفتح جوه Claude (claude.ai).':'The playground works when the platform is opened inside Claude (claude.ai).');return}
PG.trace=[];PG.out='';PG.busy=true;render();PGCTL=new AbortController();
const ask=`You are a careful business agent working for a company in Egypt or the Gulf. GOAL: ${PG.goal}
Starting dataset: ${PG.data} (read it with read_dataset). Work like an agent:
1) First write a short plan (max 4 steps) in one sentence each.
2) Use tools: read the data, use calculate for EVERY number you report, save_draft for documents.
3) Only if the goal needs something sent to a person, call send_message once with the final reviewed message; a human approves it.
4) Stop when the goal is met. Finish with a short delivery: what you did, key numbers (from calculate), what needs human review.
Never invent numbers or data. Reply in ${ar?'Egyptian Arabic':'English'}.`;
try{const {text}=await sample(ask,{tools:pgTools(),modelTier:'default',signal:PGCTL.signal,onText:({text})=>{PG.out=text;const f=document.querySelector('.pgfinal');if(f)f.innerHTML=fmtMD(text)}});PG.out=text||PG.out;if(!ST.pgXP){ST.pgXP=1;addXP(10)}}
catch(e){if(e&&e.code!=='cancelled')ntf('pgnote',e.code==='rate_limited'?(ar?'طلبات كتير — جرّب بعد شوية.':'Too many requests — try again soon.'):(ar?'الوكيل وقف بسبب خطأ. جرّب تاني.':'The agent stopped with an error. Try again.'));PG.out=(e&&e.text)||PG.out}
PG.busy=false;PGCTL=null;savePG();render()}

// --- 4. Multi-agent team designer
let TEAM=Object.assign({name:'',steps:[{a:'collections-prioritiser',ho:'',ap:false},{a:'cash-forecaster',ho:'',ap:false},{a:'board-report-writer',ho:'',ap:true}]},ST.team||{});
function saveTEAM(){ST.team=TEAM;saveST()}
const tmAgent=s=>{if(s.a&&s.a!=='custom'){const r=fdFind(s.a);if(r[1])return {f:r[0],a:r[1],n:r[1].n,job:r[1].job}}return {n:T(s.cn||'Custom agent',s.cn||'وكيل مخصص'),job:T(s.cj||'',s.cj||'')}};
function teamDiag(){const n=TEAM.steps.length;const gap=18;const w=Math.floor((640-gap*(n+1))/n);const nodes=TEAM.steps.map((s,i)=>{const x0=gap+i*(w+gap);const g=tmAgent(s);return ['t'+i,LANG==='ar'?640-x0-w:x0,110,w,70,T((s.ap?'✅ ':'')+g.n.en,(s.ap?'✅ ':'')+g.n.ar)]});const edges=TEAM.steps.slice(1).map((s,i)=>['t'+i,'t'+(i+1)]);
return {k:'team',t:T('',''),d:T('',''),nodes,edges,steps:[{on:nodes.map(x=>x[0]).concat(edges.map(e=>e[0]+'>'+e[1])),c:T('','')}]}}
function teamPrompt(lang){const en=lang==='en';let p=en?`You run a team of ${TEAM.steps.length} agents in order${TEAM.name?` («${TEAM.name}»)`:''}. For each step act as that agent, produce its outputs, check them, and pass ONLY the hand-off package to the next step. Stop and wait for my approval wherever marked. Never post, pay or send anything yourself. Use only the data I attach; write [MISSING] for gaps and label assumptions.\n`:`هتشغّل فريق من ${TEAM.steps.length} وكلاء بالترتيب${TEAM.name?` («${TEAM.name}»)`:''}. في كل خطوة اشتغل كأنك الوكيل ده، طلّع مخرجاته وراجعها، وسلّم «حزمة التسليم» بس للخطوة اللي بعدها. اقف واستنى موافقتي في الأماكن المعلّمة. ممنوع ترحّل أو تدفع أو تبعت أي حاجة بنفسك. استخدم البيانات اللي هرفقها بس؛ اكتب [MISSING] لأي نقص وعلّم الافتراضات.\n`;
TEAM.steps.forEach((s,i)=>{const g=tmAgent(s);p+=`\n## ${en?'Step':'الخطوة'} ${i+1} — ${g.n[lang]}\n${en?'Job':'المهمة'}: ${g.job[lang]||'[..]'}\n`;if(g.a)p+=`${en?'Outputs':'المخرجات'}: ${fdList(g.a.out[lang]).join('; ')}\n`;if(i<TEAM.steps.length-1)p+=`${en?'Hand-off to step':'التسليم للخطوة'} ${i+2}: ${s.ho||'[..]'}\n`;if(s.ap)p+=en?'⏸ STOP here for human approval before continuing.\n':'⏸ اقف هنا لموافقة بشرية قبل ما تكمّل.\n'});
return p+(en?'\nStart with step 1: list the inputs you need from me.':'\nابدأ بالخطوة 1: اكتب المدخلات اللي محتاجها مني.')}
function vTeam(){const ar=LANG==='ar';const lang=ar?'ar':'en';const opt=v=>`<option value="custom" ${v==='custom'?'selected':''}>✎ ${ar?'وكيل مخصص':'Custom agent'}</option>`+FD.map(f=>`<optgroup label="${esc(L(f.t))}">${f.agents.map(a=>`<option value="${a.k}" ${v===a.k?'selected':''}>${esc(L(a.n))}</option>`).join('')}</optgroup>`).join('');const pi=PSTORE.push(teamPrompt(lang))-1;
return `<p class="lede">${ar?'صمّم فريق وكلاء: رتّبهم، حدد بيتسلّموا إيه من بعض، وفين لازم موافقة بشرية. وبعدين صدّر الفريق كبرومبت واحد لـ Cowork ومعاه الـ Skills.':'Design a team of agents: order them, define what each hands to the next and where a human must approve. Then export the team as one Cowork prompt plus the Skills.'}</p>
<label class="pbf"><b>${ar?'اسم الفريق':'Team name'}</b><input class="search" data-tmn="1" value="${esc(TEAM.name)}" placeholder="${ar?'مثلاً: فريق إقفال الشهر':'e.g. Month-end team'}"></label>
<div class="tmsteps">${TEAM.steps.map((s,i)=>`<div class="tmstep"><span class="fdn">${i+1}</span><div class="tmbody"><select class="search" data-tma="${i}">${opt(s.a)}</select>${s.a==='custom'?`<input class="search" data-tmc="${i}|cn" value="${esc(s.cn||'')}" placeholder="${ar?'اسم الوكيل':'Agent name'}"><input class="search" data-tmc="${i}|cj" value="${esc(s.cj||'')}" placeholder="${ar?'المهمة الواحدة':'The one job'}">`:''}${i<TEAM.steps.length-1?`<input class="search" data-tmh="${i}" value="${esc(s.ho)}" placeholder="${ar?`بيسلّم إيه للخطوة ${i+2}؟`:`What does it hand to step ${i+2}?`}">`:''}<label class="fdrun"><input type="checkbox" data-tmp="${i}" ${s.ap?'checked':''}> ${ar?'موافقة بشرية بعد الخطوة دي':'Human approval after this step'}</label></div><div class="tmops"><button class="tbtn" data-tmo="up|${i}" ${i===0?'disabled':''}>↑</button><button class="tbtn" data-tmo="down|${i}" ${i===TEAM.steps.length-1?'disabled':''}>↓</button><button class="tbtn" data-tmo="del|${i}" ${TEAM.steps.length<3?'disabled':''}>✕</button></div></div>`).join('')}</div>
<div class="row-btns"><button class="tbtn" data-tmo="add|0" ${TEAM.steps.length>=6?'disabled':''}>＋ ${ar?'ضيف وكيل':'Add agent'}</button></div>
<section class="dgbox card">${dgSVG(teamDiag(),0)}</section>
<div class="row-btns"><button class="btn-gold copy" data-i="${pi}">${ar?'انسخ برومبت الفريق لـ Cowork':'Copy the team prompt for Cowork'}</button><button class="tbtn" data-tmx="zip">⬇ ${ar?'الفريق + الـ Skills (ZIP)':'Team + Skills (ZIP)'}</button><button class="tbtn" data-tmx="md">⬇ MD</button></div>
<details class="fdsp"><summary>🧠 ${ar?'شوف برومبت الفريق':'View the team prompt'}</summary><pre dir="auto">${esc(teamPrompt(lang))}</pre></details>`}
async function teamZip(btn){await ensureZip();const z=new JSZip();const id=slug(TEAM.name)||'agent-team';const root=z.folder(id);root.file('TEAM-PROMPT-EN.md',teamPrompt('en'));root.file('TEAM-PROMPT-AR.md',teamPrompt('ar'));TEAM.steps.forEach((s,i)=>{const g=tmAgent(s);if(g.a){const sk=fdSkill(g.a.sk);root.file(`agents/${i+1}-${g.a.k}.md`,fdPrompt(g.a,g.f,'en'));if(sk)root.folder('skills/'+sk.k).file('SKILL.md',fdSkillMd(sk,'en'))}});const ok=await saveFile(id+'.zip',await z.generateAsync({type:'blob'}));if(ok)btn.textContent='✓'}

// --- 5. Cost & time estimator
let CE=Object.assign({runs:20,manual:45,review:10,setup:6,rate:350,err0:8,err1:3},ST.ce||{});
function vCost(){const ar=LANG==='ar';const m=CE.runs*(CE.manual-CE.review)/60;const y=m*12;const val=y*CE.rate;const setupCost=CE.setup*CE.rate;const pay=m>0?setupCost/(m*CE.rate):Infinity;const errSaved=CE.runs*12*Math.max(0,CE.err0-CE.err1)/100;
const f=(k,lbl,suf)=>`<label class="pbf"><b>${lbl}</b><input class="search" type="number" min="0" data-ce="${k}" value="${CE[k]}"> <span class="k">${suf||''}</span></label>`;const bar=(v,max,c)=>`<i class="cebar"><em style="width:${Math.min(100,max?v*100/max:0)}%;background:${c}"></em></i>`;
return `<p class="lede">${ar?'قبل ما تبني وكيل، احسب: هيوفّر قد إيه، والمراجعة هتاخد قد إيه، وإمتى يرجّع تكلفة إعداده. الأرقام تقديرات إنت بتدخلها.':'Before you build an agent, estimate: time saved, review time and when the setup pays back. The numbers are your own estimates.'}</p>
<div class="twocol"><div class="abpane">${f('runs',ar?'مرات التشغيل في الشهر':'Runs per month')}${f('manual',ar?'دقايق الشغل اليدوي لكل مرة':'Manual minutes per run')}${f('review',ar?'دقايق مراجعتك لمخرج الوكيل':'Your review minutes per agent run')}${f('setup',ar?'ساعات الإعداد (مرة واحدة)':'Setup hours (one-off)')}${f('rate',ar?'تكلفة ساعة الموظف':'Hourly staff cost','EGP')}${f('err0',ar?'نسبة الأخطاء قبل':'Error rate before','%')}${f('err1',ar?'نسبة الأخطاء بعد':'Error rate after','%')}</div>
<div class="abpane"><h3>📊 ${ar?'النتيجة':'Result'}</h3><div class="cegrid"><div><span class="k">${ar?'ساعات موفّرة/شهر':'Hours saved / month'}</span><b>${m.toFixed(1)}</b></div><div><span class="k">${ar?'ساعات موفّرة/سنة':'Hours saved / year'}</span><b>${y.toFixed(0)}</b></div><div><span class="k">${ar?'قيمة الوقت/سنة':'Value of time / year'}</span><b>${Math.round(val).toLocaleString()} EGP</b></div><div><span class="k">${ar?'استرداد الإعداد':'Setup payback'}</span><b>${isFinite(pay)?pay.toFixed(1)+(ar?' شهر':' months'):'—'}</b></div><div><span class="k">${ar?'أخطاء أقل/سنة':'Fewer errors / year'}</span><b>${errSaved.toFixed(0)}</b></div></div>
<p class="k">${ar?'دقايق كل مرة':'Minutes per run'}</p><div class="cerow"><span>${ar?'يدوي':'Manual'}</span>${bar(CE.manual,CE.manual,'var(--red)')}<b>${CE.manual}</b></div><div class="cerow"><span>${ar?'وكيل + مراجعة':'Agent + review'}</span>${bar(CE.review,CE.manual,'var(--green)')}<b>${CE.review}</b></div>
<p class="note">${ar?'استخدام Claude بيتحسب من حدود خطتك؛ المهام التقيلة بتستهلك أكتر. المراجعة البشرية جزء من الحساب ومش اختيارية.':'Claude usage counts toward your plan’s limits; heavier tasks use more. Human review is part of the maths, not optional.'}</p>${m<=0?`<p class="note">⚠ ${ar?'المراجعة بتاخد وقت أكتر من الشغل اليدوي — الوكيل ده مش مستاهل دلوقتي.':'Review takes longer than doing it by hand — this agent is not worth it yet.'}</p>`:''}</div></div>`}

// ===== Workflow designer → automation hub tabs (8, 9, 11, 13) =====
let WFTAB='design';
{const _wf=vWF;vWF=function(){const ar=LANG==='ar';const tabs=`<div class="tabs big">${[['design','🔀',UX21.design],['find','🔎',UX21.find],['recipes','📗',UX21.recipes],['matrix','✅',UX21.matrix],['risk','⚠',UX21.risk]].map(t=>`<button class="tab ${WFTAB===t[0]?'on':''}" data-wftab="${t[0]}">${t[1]} ${L(t[2])}</button>`).join('')}</div>`;
if(WFTAB==='design')return _wf().replace(/(<\/h1>)/,'$1'+tabs);crumb(L(UX6.wf)+' › '+L(UX21[WFTAB]));return `<h1>🔀 ${L(UX6.wf)}</h1>`+tabs+(WFTAB==='find'?vAFind():WFTAB==='recipes'?vRecipes():WFTAB==='matrix'?vMatrix():vRisk())}}
