<div class="row-btns"><button class="tbtn" data-ama="1">＋ ${ar?'ضيف خطوة':'Add step'}</button><button class="tbtn" data-amx="md">⬇ MD</button><button class="tbtn" data-amx="csv">⬇ CSV</button></div>
