function savedSection(){const ar=LANG==='ar';return `<section class="careers"><h2>💾 ${L(UX21.saved)} (${ST.mine.length})</h2>${ST.mine.length?`<div class="fdlist">${ST.mine.slice(0,60).map((m,k)=>{const i=PSTORE.push(m.p)-1;return `<details class="fdag"><summary class="fdhead"><span class="fdt"><b>${esc(m.t)}</b><span class="k">${m.d}</span></span></summary><div class="fdbody"><pre dir="auto" class="repre">${esc(m.p)}</pre><div class="row-btns"><button class="copy" data-i="${i}">${L(UI.copy)}</button><button class="tbtn" data-rei="${i}">♻ ${ar?'حسّنه':'Re-enhance'}</button><button class="tbtn" data-stuload="${k}">🎛 ${ar?'افتح في البناء':'Open in Build'}</button><button class="tbtn" data-pbdel="${k}">✕ ${ar?'امسح':'Delete'}</button></div></div></details>`}).join('')}</div><div class="row-btns"><button class="tbtn" data-pbexp="all">⬇ ${ar?'كلهم .md':'All as .md'}</button></div>`:`<p class="k">${ar?'لسه مفيش برومبتات محفوظة — احفظ من الاستوديو أو المساعد.':'No saved prompts yet — save from the Studio or the assistant.'}</p>`}</section>`}
{const _vh=vHub;vHub=function(){return _vh()+savedSection()}}

document.addEventListener('click',e=>{const g=s=>e.target.closest(s);let x;
if(x=g('[data-pg]')){const a=x.dataset.pg;if(a==='run'&&!PG.busy)pgRun();else if(a==='stop'&&PGCTL)PGCTL.abort();else if(a==='clear'){PG.trace=[];PG.out='';savePG();render()}return}
if(x=g('[data-pga]')){if(PGWAIT)PGWAIT(x.dataset.pga==='1');return}
if(x=g('[data-pgs]')){const ar=LANG==='ar';PG.goal=x.textContent;PG.data=x.dataset.d;savePG();render();return}
if(x=g('[data-tmo]')){const [a,i]=x.dataset.tmo.split('|');const n=+i;const s=TEAM.steps;if(a==='up'&&n>0)[s[n-1],s[n]]=[s[n],s[n-1]];if(a==='down'&&n<s.length-1)[s[n+1],s[n]]=[s[n],s[n+1]];if(a==='del'&&s.length>2)s.splice(n,1);if(a==='add'&&s.length<6)s.push({a:'custom',cn:'',cj:'',ho:'',ap:false});saveTEAM();render();return}
if(x=g('[data-tmx]')){if(x.dataset.tmx==='zip')teamZip(x);else saveFile((slug(TEAM.name)||'agent-team')+'.md',teamPrompt(LANG==='ar'?'ar':'en')).then(ok=>{if(ok)x.textContent='✓'});return}
if(x=g('[data-wftab]')){WFTAB=x.dataset.wftab;render();return}
if(x=g('[data-aff]')){AF.field=x.dataset.aff;saveAF();render();return}
if(x=g('[data-af]')){if(!AF.busy)afAsk();return}
if(x=g('[data-rcat]')){RCAT=x.dataset.rcat;render();return}
if(x=g('[data-rmx]')){const r=RECIPES.find(y=>y.k===x.dataset.rmx);if(r){AM={name:L(r.t),rows:L(r.steps).map(s=>({step:s,risk:/send|email|pay|post|file|ابعت|إرسال|دفع|ترحيل/i.test(s)?'high':'low',appr:'',thr:'',ev:''}))};saveAM();WFTAB='matrix';render()}return}
if(x=g('[data-ama]')){AM.rows.push({step:'',risk:'low',appr:'',thr:'',ev:''});saveAM();render();return}
if(x=g('[data-amd]')){AM.rows.splice(+x.dataset.amd,1);saveAM();render();return}
if(x=g('[data-amx]')){if(x.dataset.amx==='md')saveFile('approval-matrix.md',amMD());else saveFile('approval-matrix.csv',BOM+['step,risk,approver,threshold,evidence'].concat(AM.rows.map(r=>[r.step,r.risk,r.appr,r.thr,r.ev].map(csvq).join(','))).join('\n'));return}
if(x=g('[data-rk]')){if(!RK.busy)rkAsk();return}
if(x=g('[data-rkx]')){const rows=rkRows();if(x.dataset.rkx==='csv')saveFile('risk-register.csv',BOM+['risk,category,impact,likelihood,score,control,owner'].concat(rows.map(r=>[r.t,r.cat,r.sev,r.lik,r.sev*r.lik,r.ctrl,r.owner].map(csvq).join(','))).join('\n'));else saveFile('risk-register.md','# Risk register\n\n| Risk | Cat | I | L | Score | Control | Owner |\n|---|---|---|---|---|---|---|\n'+rows.map(r=>`| ${r.t} | ${r.cat} | ${r.sev} | ${r.lik} | ${r.sev*r.lik} | ${r.ctrl} | ${r.owner} |`).join('\n'));return}
if(x=g('[data-m3tab]')){M3TAB=x.dataset.m3tab;render();return}
if(x=g('[data-agc]')){AGC=x.dataset.agc;render();return}
if(x=g('[data-dlk]')){DL2.k=x.dataset.dlk;DL2.sel=[0,1,2];ST.dl2=DL2;saveST();render();return}
if(x=g('[data-bka]')){BK.c.push('#888888');ST.bk=BK;saveST();render();return}
if(x=g('[data-fgc]')){FGC=x.dataset.fgc;render();return}
if(x=g('[data-fx2]')){if(!FX.busy)fixDiag();return}},true);
document.addEventListener('toggle',e=>{const d=e.target;if(d&&d.dataset&&d.dataset.fgk&&d.open){ST.fgSeen=Object.assign({},ST.fgSeen);if(!ST.fgSeen[d.dataset.fgk]){ST.fgSeen[d.dataset.fgk]=1;if(typeof FAILS2!=='undefined'&&Object.keys(ST.fgSeen).length===FAILS2.length)addXP(15);saveST()}}},true);
document.addEventListener('change',e=>{const t=e.target,d=t.dataset||{};
if(t.id==='pgdata'){PG.data=t.value;savePG();return}if(t.id==='pgappr'){PG.appr=t.checked;savePG();return}
if(d.tma!==undefined){TEAM.steps[+d.tma].a=t.value;saveTEAM();render();return}if(d.tmp!==undefined){TEAM.steps[+d.tmp].ap=t.checked;saveTEAM();render();return}
if(d.afk){AF.sel=Object.assign({},AF.sel);if(t.checked)AF.sel[d.afk]={};else delete AF.sel[d.afk];saveAF();render();return}
if(d.rkk){RK.sel=Object.assign({},RK.sel);if(t.checked)RK.sel[d.rkk]={};else delete RK.sel[d.rkk];saveRK();render();return}
if(d.rks){const [k,f]=d.rks.split('|');RK.sel[k][f]=+t.value;saveRK();render();return}
if(d.amr&&t.tagName==='SELECT'){const [i,f]=d.amr.split('|');AM.rows[+i][f]=t.value;saveAM();return}
if(d.wz&&t.tagName==='SELECT'){WZ[d.wz]=t.value;ST.wz=WZ;saveST();render();return}
if(d.br&&t.tagName==='SELECT'){BR[d.br]=t.value;ST.br=BR;saveST();render();return}
if(d.bkc!==undefined){BK.c[+d.bkc]=t.value;ST.bk=BK;saveST();render();return}
if(d.dls!==undefined){const j=+d.dls;DL2.sel=t.checked?DL2.sel.concat(j):DL2.sel.filter(v=>v!==j);ST.dl2=DL2;saveST();render();return}
if(d.bad){const [k,i]=d.bad.split('|');ST.ba=Object.assign({},ST.ba);const a=(ST.ba[k]||[]).slice();const n=+i;if(t.checked&&!a.includes(n)){a.push(n);ST.baXP=Object.assign({},ST.baXP);if(!ST.baXP[k+n]){ST.baXP[k+n]=1;addXP(5)}}if(!t.checked&&a.includes(n))a.splice(a.indexOf(n),1);ST.ba[k]=a;saveST();render();return}});
let _r14t=null;const r14rerender=(sel)=>{clearTimeout(_r14t);_r14t=setTimeout(()=>{const a=document.activeElement;const key=a&&a.getAttribute&&(a.getAttribute('data-'+sel)!==null?sel:null);const val=a&&a.dataset?JSON.stringify(a.dataset):'';const pos=a&&a.selectionStart;render();if(val){const d=JSON.parse(val);const k=Object.keys(d)[0];const n=document.querySelector(`[data-${k.replace(/[A-Z]/g,m=>'-'+m.toLowerCase())}="${d[k]}"]`);if(n){n.focus();try{n.setSelectionRange(pos,pos)}catch(e){}}}},500)};
document.addEventListener('input',e=>{const t=e.target,d=t.dataset||{};
if(t.id==='pggoal'){PG.goal=t.value;savePG();return}if(d.tmn){TEAM.name=t.value;saveTEAM();return}if(d.tmh!==undefined){TEAM.steps[+d.tmh].ho=t.value;saveTEAM();return}if(d.tmc){const [i,f]=d.tmc.split('|');TEAM.steps[+i][f]=t.value;saveTEAM();return}
if(d.ce){CE[d.ce]=Math.max(0,Number(t.value)||0);ST.ce=CE;saveST();r14rerender('ce');return}
if(d.afm){AF.sel[d.afm].m=Math.max(1,Number(t.value)||1);saveAF();r14rerender('afm');return}if(t.id==='afweek'){AF.week=t.value;saveAF();return}
if(d.amn){AM.name=t.value;saveAM();return}if(d.amr&&t.tagName!=='SELECT'){const [i,f]=d.amr.split('|');AM.rows[+i][f]=t.value;saveAM();return}
if(t.id==='rkdesc'){RK.desc=t.value;saveRK();return}
if(d.wz&&t.tagName!=='SELECT'){WZ[d.wz]=t.value;ST.wz=WZ;saveST();r14rerender('wz');return}if(d.br&&t.tagName!=='SELECT'){BR[d.br]=t.value;ST.br=BR;saveST();r14rerender('br');return}
if(d.bkh!==undefined){BK.c[+d.bkh]=t.value;ST.bk=BK;saveST();if(hexRgb(t.value))r14rerender('bkh');return}if(d.dla){DL2.aud=t.value;ST.dl2=DL2;saveST();r14rerender('dla');return}
if(t.id==='fxo2'){FX.out=t.value;return}});
